def main():
    rows = []
    for t in Q:
        year, course, qno, marks, page, teacher, lesson, typ, grp, question = t[:10]
        rows.append(dict(year=year, course=course, qno=qno, marks=marks, page=page, teacher=teacher,
                         lesson=f"L{lesson}" if lesson else "", type=typ, group=grp, question=question,
                         in_notes=t[10] if len(t) > 10 else ""))
    out = os.path.join(os.path.dirname(__file__), "questions.json")
    with open(out, "w", encoding="utf-8") as f:
        json.dump(rows, f, ensure_ascii=False, indent=1)
    from collections import Counter
    print(len(rows), Counter(r["teacher"] for r in rows))
    print(Counter((r["course"], r["year"]) for r in rows))


if __name__ == "__main__":
    main()
